 }
 checkAllExercisesCompleted();
 });
// Configuration
const motivationalQuotes = {
 daily: [
 "Sweat is just fat crying! 💦",
 "Your phone isn't the only thing that needs charging 🔋",
 "The only bad workout is the one you didn't do! 💪",
 "Did someone say pizza? 🍕 (Do 10 more reps!)"
 ],
 completion: [
 "Another day, another slay! 💅",
 "You're stronger than yesterday! 💥",
 "Gains goblin mode activated! 🧌",
 "Who needs superpowers when you have gains? 🦸"
 ]
 };
 // Local Storage Configuration
 const STORAGE_KEYS = {
 STREAK: 'fitquest_streak',
 LAST_COMPLETED: 'fitquest_last_completed',
 CHECKED_EXERCISES: 'fitquest_checked_exercises'
 };
 // Enhanced State Management
 let workoutState = {
 streak: localStorage.getItem(STORAGE_KEYS.STREAK) || 0,
 lastCompleted: localStorage.getItem(STORAGE_KEYS.LAST_COMPLETED) || '',
 checkedExercises: JSON.parse(localStorage.getItem(STORAGE_KEYS.CHECKED_EXERCISES)) || {}
 };

 // Init
 $(document).ready(() => {
 // Set current day
 const days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
 const today = new Date().getDay();
 const currentDay = days[today === 0 ? 6 : today-1]; // Adjust for week start
 $('#currentDay').val(currentDay);

 // Restore checked states
 $('.exercise-checkbox').each(function() {
 const exerciseId = $(this).closest('.exercise').find('h5').text();
 $(this).prop('checked', !!workoutState.checkedExercises[exerciseId]);
 });

 // Initialize filters
 $('#dayFilter, #tagFilter').on('change', filterWorkouts);
 filterWorkouts();
 updateDateTime();
 updateGreeting();
 loadProgress();
 setInterval(updateDateTime, 1000);
 setInterval(rotateQuote, 15000);
 });

 // Core Functions
 function updateDateTime() {
 const now = new Date();
 document.getElementById('dateTime').textContent = now.toLocaleTimeString('en-US', {
 hour: '2-digit',
 minute: '2-digit'
 });
 }

 function updateGreeting() {
 const hour = new Date().getHours();
 const greetings = ["🌞 Rise and Shine!", "💥 Crush Your Day!", "🌙 Night Gains!"];
 document.getElementById('greeting').textContent = greetings[Math.floor(hour / 8)];
 }

 function rotateQuote() {
 $('#quoteOfTheDay').fadeOut(500, () => {
 $(this).text(motivationalQuotes.daily[Math.floor(Math.random() * motivationalQuotes.daily.length)]).fadeIn(500);
 });
 }

 // Fixed Filter Function
 function filterWorkouts() {
 const selectedDay = $('#dayFilter').val().toLowerCase().trim();
 const selectedTag = $('#tagFilter').val().toLowerCase().trim();
 let hasVisible = false;

 $('.workout-day').each(function() {
 const day = $(this).data('day').toLowerCase();
 const tags = $(this).data('tags').toString().toLowerCase();
 const dayMatch = !selectedDay || day === selectedDay;
 const tagMatch = !selectedTag || tags.includes(selectedTag);

 if (dayMatch && tagMatch) {
 $(this).show().addClass('active-day');
 hasVisible = true;
 } else {
 $(this).hide().removeClass('active-day');
 }
 });

 $('#workoutContainer').toggleClass('no-workouts', !hasVisible);
 updateProgress();
 }

 // Fixed Progress Tracking
 function updateProgress() {
 const currentDay = $('#currentDay').val();
 const dayExercises = $(`.workout-day[data-day="${currentDay}"] .exercise-checkbox`);
 const completed = dayExercises.filter(':checked').length;
 const progress = (completed / dayExercises.length) * 100 || 0;

 $('#dailyProgress').css('width', `${progress}%`);
 if (completed === dayExercises.length) showCompletion();
 }

 function showCompletion() {
 updateStreak();
 triggerConfettiBurst();

 // Prepare share data
 const emojis = ["🏆", "💪", "🔥", "🚀"];
 $('#completionEmoji').text(emojis[Math.floor(Math.random() * emojis.length)]);
 $('#completionQuote').text(motivationalQuotes.completion[Math.floor(Math.random() * motivationalQuotes.completion.length)]);
 $('#shareStreak').text(workoutState.streak);
 $('#shareDate').text(new Date().toLocaleDateString());

 $('#shareModal').modal('show');
 }

 // Fixed Streak Management
 function updateStreak() {
 const today = new Date().toDateString();
 const lastCompleted = new Date(workoutState.lastCompleted);
 const isNewDay = today !== workoutState.lastCompleted;
 const isConsecutive = lastCompleted.setDate(lastCompleted.getDate()+1) === new Date(today).getTime();

 if (isNewDay) {
 workoutState.streak = isConsecutive ? workoutState.streak + 1 : 1;
 workoutState.lastCompleted = today;
 localStorage.setItem(STORAGE_KEYS.STREAK, workoutState.streak);
 localStorage.setItem(STORAGE_KEYS.LAST_COMPLETED, today);
 }

 $('#streakCounter').text(`🔥 ${workoutState.streak} Day Streak`);
 }

 // Fixed Checkbox Persistence
 function saveCheckedState(exerciseId, isChecked) {
 workoutState.checkedExercises[exerciseId] = isChecked;
 localStorage.setItem(STORAGE_KEYS.CHECKED_EXERCISES, JSON.stringify(workoutState.checkedExercises));
 }

