 function triggerConfettiBurst() {
 confetti({
 particleCount: 100,
 spread: 70,
 origin: { y: 0.6 },
 colors: ['#ff0000', '#00ff00', '#0000ff']
 });
 }

 $('.exercise-checkbox').on('change', function() {
 const exerciseId = $(this).closest('.exercise').find('h5').text();
 const isChecked = $(this).prop('checked');

 $(this).closest('.exercise').toggleClass('completed-exercise', isChecked);
 saveCheckedState(exerciseId, isChecked);
 updateProgress();
 if(isChecked) triggerConfetti();
 });

 // Mobile-Friendly Confetti
 function triggerConfetti() {
 confetti({
 particleCount: 30,
 spread: 60,
 origin: { y: 0.6 },
 colors: ['#ff0000', '#00ff00', '#0000ff']
 });
 }
 </script>
